// Obtain a millisecond-resolution time reading intended for difference calculations
// The function returns a value (time_millis is typedef unsigned int). We materialize
// it into a heap-allocated object so the fuzzer runtime can persist it as a time_millis *.

// Call the target API
time_millis now = time_get_millis();

// Allocate output object and store the reading
time_millis *time = new time_millis;  // owned by the fuzzer runtime after return
*time = now;

// Tag the object with metadata for downstream stubs (not strictly required, but helpful)
FUZZ_SET_ATTR_STR(time, "role", "reading");

// Validation summary: This stub captures the returned value into a persistent object and
// avoids assuming absolute/monotonic semantics; no additional constraints are required.

// Generate a value in the time_millis domain (unsigned int) and set the subsystem's time
unsigned int v = *FUZZ_PARAM(unsigned int);

// Call the target API
// Requirement: millis is an unsigned int representing milliseconds; wrap-around semantics follow unsigned.
time_set_millis((time_millis)v);

// Postcondition from API: subsequent time_get_millis calls reflect this set value.
// We validate this explicitly to ensure correct behavior under fuzzing.
time_millis check = time_get_millis();
FUZZ_ASSERT(check == (time_millis)v, "time_get_millis did not reflect time_set_millis value");

